function randInt(max: number): number {
  if (!(max > 0)) return 0;
  const buf = new Uint32Array(1);
  const limit = Math.floor(4294967296 / max) * max;
  let value = 0;
  do {
    crypto.getRandomValues(buf);
    value = buf[0];
  } while (value >= limit);
  return value % max;
}

function randomHex(bytes: number): string {
  const buf = new Uint8Array(bytes);
  crypto.getRandomValues(buf);
  let out = '';
  for (let i = 0; i < buf.length; i += 1) out += buf[i].toString(16).padStart(2, '0');
  return out;
}

function send(ws: any, payload: any) {
  if (!ws || ws.readyState !== 1) return;
  try {
    ws.send(JSON.stringify(payload));
  } catch (err) { /* socket died between checks */ }
}

function sendTo(player: any, payload: any) {
  if (!player || !player.connected) return;
  send(player.socket, payload);
}

function broadcast(room: any, payload: any, exceptId?: string) {
  room.players.forEach((player: any) => {
    if (player.id !== exceptId) sendTo(player, payload);
  });
}

function cleanName(value: any): string {
  const name = String(value == null ? '' : value)
    .replace(/[\u0000-\u001f\u007f<>]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 10);
  return name || '无名酒客';
}

function cleanAvatar(value: any): string {
  return /^v[1-6]$/.test(String(value || '')) ? String(value) : 'v1';
}

function cleanText(value: any, max?: number): string {
  return String(value == null ? '' : value)
    .replace(/[\u0000-\u001f\u007f<>]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max || 24);
}

function randomItem(): string {
  return ITEMS[randInt(ITEMS.length)];
}

/* ------------------------------------------------------------------ */
/* 跨实例中继                                                          */
/*                                                                     */
/* Deno Deploy 会把不同的 WebSocket 连接分到不同 isolate，内存里的      */
/* rooms 互不可见，表现为「刚建好的房间，别人加入时提示不存在」。       */
/* 下面用 Deno KV 做一层消息中继：房间仍然只存在于房主 isolate，客人   */
/* isolate 把消息转发过去，再把房主发回来的消息投递给本地 socket。     */
/* 默认就尝试开启：Deno Deploy 的环境变量在不同部署方式下并不完全一致， */
/* 只靠 DENO_DEPLOYMENT_ID 判断会导致线上悄悄退回单实例内存模式。       */
/* 本地没有 --unstable-kv 时 openKv 会失败，自动退回内存模式；测试可用   */
/* RELAY=0 显式关闭。                                                  */
/* ------------------------------------------------------------------ */

const RELAY_ENABLED = Deno.env.get('RELAY') !== '0';
const INSTANCE_ID = randomHex(8);
const RELAY_POLL_MS = Math.max(80, Number(Deno.env.get('RELAY_POLL_MS') || 200));
const RELAY_TTL_MS = 60 * 1000;
const ROOM_OWNER_TTL_MS = 2 * 60 * 1000;
let relayKv: any = null;
let relayError = '';
const relaySeqMap = new Map<string, number>();
const remoteConns = new Map<string, any>();
const remoteSessions = new Map<number, any>();
const inboxWatchers = new Map<string, any>();

if (RELAY_ENABLED) {
  try {
    const kvPath = Deno.env.get('KV_PATH');
    const openKv = (Deno as any).openKv;
    if (typeof openKv !== 'function') throw new Error('当前运行时不支持 Deno.openKv');
    relayKv = kvPath ? await openKv(kvPath) : await openKv();
    console.log(`[relay] instance ${INSTANCE_ID} ready (v${VERSION})`);
  } catch (err) {
    relayError = String((err && (err as any).message) || err || 'KV unavailable').slice(0, 160);
    console.warn('[relay] Deno KV 不可用，退回单实例内存模式：', relayError);
    relayKv = null;
  }
} else {
  relayError = 'disabled by RELAY=0';
}

function relaySeqKey(value: number): string {
  return String(value).padStart(12, '0');
}

function nextRelaySeq(target: string): number {
  const next = (relaySeqMap.get(target) || 0) + 1;
  relaySeqMap.set(target, next);
  return next;
}

function ownerKey(code: string): string[] {
  return ['room-owner', code];
}

function inboxPrefix(code: string, owner: string): string[] {
  return ['relay-inbox', code, owner];
}

function outPrefix(code: string, inst: string, connId: number): string[] {
  return ['relay-out', code, inst, String(connId)];
}

async function registerRoomOwner(code: string): Promise<void> {
  if (!relayKv) return;
  try {
    await relayKv.set(ownerKey(code), { owner: INSTANCE_ID, at: Date.now() }, { expireIn: ROOM_OWNER_TTL_MS });
  } catch (err) {
    console.error('[relay] register owner failed', code, err);
  }
}

async function unregisterRoomOwner(code: string): Promise<void> {
  if (!relayKv) return;
  try { await relayKv.delete(ownerKey(code)); } catch (err) { /* ignore */ }
}

async function lookupRoomOwner(code: string): Promise<string> {
  if (!relayKv) return '';
  try {
    const entry = await relayKv.get(ownerKey(code));
    return entry && entry.value && entry.value.owner ? String(entry.value.owner) : '';
  } catch (err) {
    return '';
  }
}

async function pushInbox(code: string, owner: string, from: string, connId: number, payload: any): Promise<boolean> {
  if (!relayKv) return false;
  const target = `in:${code}:${owner}:${from}:${connId}`;
  const seq = nextRelaySeq(target);
  try {
    await relayKv.set(
      [...inboxPrefix(code, owner), from, String(connId), relaySeqKey(seq)],
      { payload, at: Date.now() },
      { expireIn: RELAY_TTL_MS }
    );
    return true;
  } catch (err) {
    console.error('[relay] inbox push failed', err);
    return false;
  }
}

function pushOut(code: string, inst: string, connId: number, payload: any): void {
  if (!relayKv) return;
  const target = `out:${code}:${inst}:${connId}`;
  const seq = nextRelaySeq(target);
  relayKv.set(
    [...outPrefix(code, inst, connId), relaySeqKey(seq)],
    { payload, at: Date.now() },
    { expireIn: RELAY_TTL_MS }
  ).catch((err: any) => console.error('[relay] out push failed', err));
}

function makeProxySocket(code: string, toInst: string, connId: number, remoteKey: string): any {
  return {
    readyState: 1,
    send(raw: string) {
      let payload: any;
      try { payload = JSON.parse(String(raw)); } catch (err) { return; }
      pushOut(code, toInst, connId, payload);
    },
    close() {
      pushOut(code, toInst, connId, { t: '__close' });
      remoteConns.delete(remoteKey);
    }
  };
}

function getRemoteConn(code: string, from: string, connId: string): any {
  const remoteKey = `${from}:${connId}`;
  let conn = remoteConns.get(remoteKey);
  if (!conn) {
    connSeq += 1;
    conn = {
      id: connSeq,
      ws: makeProxySocket(code, from, Number(connId), remoteKey),
      roomCode: null,
      playerId: null,
      openedAt: Date.now(),
      lastSeen: Date.now(),
      windowStart: Date.now(),
      windowCount: 0,
      remoteKey
    };
    remoteConns.set(remoteKey, conn);
  }
  conn.lastSeen = Date.now();
  return conn;
}

function dropRemoteConn(from: string, connId: string): void {
  const remoteKey = `${from}:${connId}`;
  const conn = remoteConns.get(remoteKey);
  if (!conn) return;
  remoteConns.delete(remoteKey);
  onSocketClose(conn, conn.ws);
}

function startRemoteSession(conn: any, code: string, owner: string, msg: any): void {
  const session = {
    conn,
    code,
    owner,
    closed: false,
    timer: null as any,
    last: 0,
    gapAt: 0,
    startedAt: Date.now()
  };
  conn.remote = session;
  remoteSessions.set(conn.id, session);
  const tick = async () => {
    if (session.closed) return;
    try { await drainOutbox(session); } catch (err) { console.error('[relay] outbox drain failed', err); }
    if (!session.closed && !conn.roomCode && Date.now() - session.startedAt > 12000) {
      send(conn.ws, { t: 'error', code: 'RELAY_TIMEOUT', message: '房间服务没有响应，再试一次。' });
      closeRemoteSession(conn, true);
      return;
    }
    if (!session.closed) session.timer = setTimeout(tick, RELAY_POLL_MS);
  };
  session.timer = setTimeout(tick, 0);
  pushInbox(code, owner, INSTANCE_ID, conn.id, msg).then((ok) => {
    if (!ok && !session.closed) {
      send(conn.ws, { t: 'error', code: 'RELAY_FAILED', message: '房间服务暂时不可用，再试一次。' });
      closeRemoteSession(conn, false);
    }
  }).catch((err) => console.error('[relay] join forward failed', err));
}

async function drainOutbox(session: any): Promise<void> {
  if (!relayKv || session.closed) return;
  const entries: any[] = [];
  for await (const entry of relayKv.list({ prefix: outPrefix(session.code, INSTANCE_ID, session.conn.id) })) {
    const seq = Number(entry.key[entry.key.length - 1]);
    if (!Number.isFinite(seq)) continue;
    entries.push({ seq, entry });
  }
  entries.sort((a, b) => a.seq - b.seq);
  for (const item of entries) {
    if (session.closed) return;
    if (item.seq !== session.last + 1) {
      if (!session.gapAt) session.gapAt = Date.now();
      if (Date.now() - session.gapAt < 4000) break;
      /* 上一条消息确实丢了，跳过缺口，避免整条会话卡死。 */
    } else {
      session.gapAt = 0;
    }
    session.last = item.seq;
    await relayKv.delete(item.entry.key).catch(() => {});
    deliverRemote(session, item.entry.value && item.entry.value.payload);
  }
}

function deliverRemote(session: any, payload: any): void {
  if (!payload || typeof payload !== 'object') return;
  const conn = session.conn;
  if (payload.t === '__close') {
    closeRemoteSession(conn, false);
    return;
  }
  if (payload.t === 'joined') {
    conn.roomCode = payload.code || null;
    conn.playerId = payload.playerId || null;
  }
  if (payload.t === 'error') {
    const code = String(payload.code || '');
    if (code === 'ROOM_NOT_FOUND' || code === 'RECONNECT_FAILED' || code === 'ROOM_CLOSED') {
      conn.roomCode = null;
      conn.playerId = null;
    }
  }
  send(conn.ws, payload);
  if (payload.t === 'error') {
    const code = String(payload.code || '');
    if (code === 'ROOM_NOT_FOUND' || code === 'RECONNECT_FAILED' || code === 'ROOM_CLOSED') {
      closeRemoteSession(conn, false);
    }
  }
}

function closeRemoteSession(conn: any, notifyOwner: boolean): void {
  const session = conn.remote;
  if (!session) return;
  session.closed = true;
  clearTimeout(session.timer);
  remoteSessions.delete(conn.id);
  conn.remote = null;
  conn.roomCode = null;
  conn.playerId = null;
  if (notifyOwner) {
    pushInbox(session.code, session.owner, INSTANCE_ID, conn.id, { t: '__close' })
      .catch((err) => console.error('[relay] close forward failed', err));
  }
}

function startInboxWatcher(code: string): void {
  if (!relayKv || inboxWatchers.has(code)) return;
  const state = { code, running: true, timer: null as any, last: new Map<string, number>(), gapAt: new Map<string, number>() };
  inboxWatchers.set(code, state);
  const tick = async () => {
    if (!state.running) return;
    try { await drainInbox(state); } catch (err) { console.error('[relay] inbox drain failed', err); }
    if (state.running) state.timer = setTimeout(tick, RELAY_POLL_MS);
  };
  state.timer = setTimeout(tick, 0);
}

function stopInboxWatcher(code: string): void {
  const state = inboxWatchers.get(code);
  if (!state) return;
  state.running = false;
  clearTimeout(state.timer);
  inboxWatchers.delete(code);
}

async function drainInbox(state: any): Promise<void> {
  if (!relayKv || !state.running) return;
  const groups = new Map<string, any>();
  for await (const entry of relayKv.list({ prefix: inboxPrefix(state.code, INSTANCE_ID) })) {
    const key = entry.key;
    const from = String(key[3]);
    const connId = String(key[4]);
    const seq = Number(key[5]);
    if (!from || !connId || !Number.isFinite(seq)) continue;
    const groupKey = `${from}:${connId}`;
    if (!groups.has(groupKey)) groups.set(groupKey, { from, connId, entries: [] });
    groups.get(groupKey).entries.push({ seq, entry });
  }
  for (const group of groups.values()) {
    group.entries.sort((a: any, b: any) => a.seq - b.seq);
    const groupKey = `${group.from}:${group.connId}`;
    let last = state.last.get(groupKey) || 0;
    for (const item of group.entries) {
      if (item.seq <= last) {
        await relayKv.delete(item.entry.key).catch(() => {});
        continue;
      }
      if (item.seq !== last + 1) {
        const gapAt = state.gapAt.get(groupKey) || 0;
        if (!gapAt) state.gapAt.set(groupKey, Date.now());
        if (!gapAt || Date.now() - gapAt < 4000) break;
      } else {
        state.gapAt.delete(groupKey);
      }
      last = item.seq;
      state.last.set(groupKey, last);
      await relayKv.delete(item.entry.key).catch(() => {});
      const payload = item.entry.value && item.entry.value.payload;
      if (!payload || typeof payload !== 'object') continue;
      if (payload.t === '__close') {
        dropRemoteConn(group.from, group.connId);
        continue;
      }
      const conn = getRemoteConn(state.code, group.from, group.connId);
      await handleMessage(conn, payload);
    }
  }
}

setInterval(() => {
  if (!relayKv) return;
  rooms.forEach((room: any) => {
    if (connectedPlayers(room).length) registerRoomOwner(room.code);
    else unregisterRoomOwner(room.code);
  });
}, 30000);

/* 房间规则：原版模式固定关闭特殊牌与道具；自定义模式逐项生效。
 * 没带配置的旧客户端按自定义全开处理，保持原有牌局行为。 */
const DEFAULT_SETTINGS = { mode: 'custom', enableSpecial: true, enableItems: true };

function normalizeSettings(input: any): any {
  const raw = input && typeof input === 'object' ? input : DEFAULT_SETTINGS;
  if (raw.mode === 'original') {
    return { mode: 'original', enableSpecial: false, enableItems: false };
  }
  const enableSpecial = raw.enableSpecial !== false;
  const enableItems = raw.enableItems !== false;
  if (!enableSpecial && !enableItems) {
    return { mode: 'original', enableSpecial: false, enableItems: false };
  }
  return { mode: 'custom', enableSpecial, enableItems };
}

